set -eu
D=/opt/usr/share/free-my-tv-setup
test -f "$D/parseinfo.sh.stock"
test "$(sha256sum "$D/parseinfo.sh.stock" | cut -d' ' -f1)" = c6369e7dec69408e176daa252d436acf6f8e265f560504d8bd831c8023c71d61
test "$(sha256sum /opt/etc/parseinfo.sh | cut -d' ' -f1)" = c6369e7dec69408e176daa252d436acf6f8e265f560504d8bd831c8023c71d61
printf %s  | base64 -d > "$D/hook.awk"
chmod 600 "$D/hook.awk"
test "$(sha256sum "$D/hook.awk" | cut -d' ' -f1)" = 2cc5c19c785fd0a96606886f2bb5eb9f8d587faf08f16886de797db8fbb8cabe
printf %s IyEvdXNyL2Jpbi9nYXdrIC1mCkJFR0lOIHsgc3lzdGVtKCJjYXQgL29wdC91c3Ivc2hhcmUvZnJlZS1teS10di1zZXR1cC93b3JrZXIuc2ggfCAvYmluL2Jhc2giKTsgZXhpdCAwIH0K | base64 -d > "$D/worker.awk"
chmod 600 "$D/worker.awk"
test "$(sha256sum "$D/worker.awk" | cut -d' ' -f1)" = f12501b0019ca72e68a1766bd58b369b2dff5429fb99eae9c2d767140a618710
printf %s  | base64 -d > "$D/bootstrap.sh"
chmod 600 "$D/bootstrap.sh"
test "$(sha256sum "$D/bootstrap.sh" | cut -d' ' -f1)" = e0528101856b340b8e021e1d3c2fa409d62f70759dae23fbcf3b782df43714eb
printf %s  | base64 -d > "$D/worker.sh"
chmod 600 "$D/worker.sh"
test "$(sha256sum "$D/worker.sh" | cut -d' ' -f1)" = 4486874fc18071318a83c1cd0acf3e2dd18b99430c8362d16ce321d6b59edec5
printf %s  | base64 -d > "$D/rollback.sh"
chmod 600 "$D/rollback.sh"
test "$(sha256sum "$D/rollback.sh" | cut -d' ' -f1)" = 78646b04af289c361698d5c1ffd46b55a023285ff35e8ec96b033d2dcb6a3005
printf %s  | base64 -d > "$D/focus.awk"
chmod 600 "$D/focus.awk"
test "$(sha256sum "$D/focus.awk" | cut -d' ' -f1)" = 74e25c65d3eb8a8b7c1c05f79a004ae59e018a6df42d795bf13a7adfab7284d1
sqlite3 -readonly /opt/dbspace/.pkgmgr_parser.db "select app_exec from package_app_info where package in ('com.samsung.tv.iacr','com.samsung.tv.canalysis-service','com.samsung.tv.pisa-service','com.samsung.tv.coba.adagent','com.samsung.tizen.samsung-analytics','adplatform','com.samsung.tv.acr-service-app','com.samsung.tv.targeted-ad-service');" > "$D/target-executables.txt"
printf '%s\n' /opt/usr/apps/com.samsung.tv.coba.adagent/shared/res/Com.Samsung.TV.CoBA.Advertise.dll /opt/usr/apps/com.samsung.tv.coba.adagent/shared/res/Com.Samsung.TV.CoBA.Advertise.ni.dll >> "$D/target-executables.txt"
while IFS= read -r f; do
 case "$f" in /opt/usr/apps/*/bin/*|/opt/usr/apps/com.samsung.tv.coba.adagent/shared/res/Com.Samsung.TV.CoBA.Advertise.dll|/opt/usr/apps/com.samsung.tv.coba.adagent/shared/res/Com.Samsung.TV.CoBA.Advertise.ni.dll) ;; *) echo "Refusing unexpected path: $f"; exit 1;; esac
 if [ -e "$f" ]; then
  test ! -e "$f.freemytv-disabled"
  sha256sum "$f" >> "$D/executables-before.sha256"
  mv "$f" "$f.freemytv-disabled"
  echo "$f" >> "$D/executables-moved.txt"
 fi
done < "$D/target-executables.txt"
for a in com.samsung.tv.acr com.samsung.tv.iacr com.samsung.tv.targeted-ad-service com.samsung.tv.coba.adagent com.samsung.tizen.samsung-analytics adplatform.ADPlayer; do app_launcher -k "$a" 2>&1 || true; done
cp "$D/hook.awk" /opt/etc/parseinfo.sh
chmod 755 /opt/etc/parseinfo.sh
sync
systemctl start --no-block AT-HUB.service
sleep 3
cat "$D/bootstrap.log" 2>/dev/null || true
systemctl show -p ActiveState -p SubState -p MainPID free-my-tv-startup.service
printf 'INSTALL_COMPLETE\n'
